#!/usr/bin/env sh
# fetch VRR / openVRR (Verkehrsverbund Rhein-Ruhr) (DE) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://www.opendata-oepnv.de/dataset/496eea5d-d6ef-4dc2-aeb0-d15c4fbf3178/resource/384d7949-4cc2-49c4-9529-68cb6eff4a8d/download/20250715_gtfs_vrr_od.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
